"use client";

import { useCallback, useEffect, useState, useTransition } from "react";
import {
  getParticipationRanks,
  type ParticipationRanks,
} from "@/app/invite-actions";

/**
 * ParticipationBadge — compact rank display + share-the-badge CTA.
 *
 * The operator's 2026-05-02 amendment: this REPLACES the cut ballot-card share
 * path. The badge image embeds NO candidate / position / score data —
 * just the user's participation rank in three scopes. Privacy-safe to
 * share publicly.
 *
 * The OG image is generated by /api/badge/og — also session-gated so the
 * URL alone (without cookies) won't render someone else's rank.
 */

const APP_URL =
  process.env.NEXT_PUBLIC_APP_URL ?? "https://ballotbridge.org";

export default function ParticipationBadge() {
  const [ranks, setRanks] = useState<ParticipationRanks | null>(null);
  const [isPending, startTransition] = useTransition();

  useEffect(() => {
    startTransition(async () => {
      const r = await getParticipationRanks();
      setRanks(r);
    });
  }, []);

  const handleShare = useCallback(async () => {
    try {
      const res = await fetch("/api/badge/og");
      if (!res.ok) return;
      const blob = await res.blob();
      const file = new File([blob], "ballot-bridge-badge.png", {
        type: "image/png",
      });
      if (
        typeof navigator !== "undefined" &&
        navigator.share &&
        navigator.canShare?.({ files: [file] })
      ) {
        await navigator.share({
          title: "I finished my ballot match",
          text: "I just finished my ballot match on Havesay.",
          files: [file],
        });
      } else if (typeof navigator !== "undefined" && navigator.share) {
        await navigator.share({
          title: "Havesay",
          text: "I just finished my ballot match.",
          url: `${APP_URL}/`,
        });
      } else {
        // Fall back to download
        const url = URL.createObjectURL(blob);
        const a = document.createElement("a");
        a.href = url;
        a.download = "ballot-bridge-badge.png";
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
      }
    } catch {
      // User cancelled or fetch failed — silent.
    }
  }, []);

  if (isPending && !ranks) return null;
  if (!ranks?.completed_at || !ranks.national) return null;

  return (
    <section
      aria-label="Participation rank"
      className="rounded-2xl border border-[var(--color-border)] bg-[var(--color-bg)] p-5 sm:p-6"
    >
      <h2 className="text-lg font-bold text-[var(--color-primary)] mb-1">
        You finished your match.
      </h2>
      <p className="text-sm text-[var(--color-text-secondary)] mb-3">
        You&rsquo;re the{" "}
        <strong className="text-[var(--color-text)]">
          {formatRank(ranks.national.rank)}
        </strong>
        {ordinalSuffix(ranks.national.rank)} person to finish a ballot match
        nationally
        {ranks.state && (
          <>
            ,{" "}
            <strong className="text-[var(--color-text)]">
              {formatRank(ranks.state.rank)}
            </strong>
            {ordinalSuffix(ranks.state.rank)} in {ranks.state.state}
          </>
        )}
        {ranks.district && (
          <>
            ,{" "}
            <strong className="text-[var(--color-text)]">
              {formatRank(ranks.district.rank)}
            </strong>
            {ordinalSuffix(ranks.district.rank)} in {ranks.district.state}-
            {ranks.district.district}
          </>
        )}
        .
      </p>
      <p className="text-xs text-[var(--color-text-muted)] mb-4">
        The shared image shows your rank only — no candidate, no party, no
        match score.
      </p>
      <button
        type="button"
        onClick={handleShare}
        className="civic-btn-primary px-4 py-2 text-sm"
      >
        Share my participation rank
      </button>
    </section>
  );
}

function formatRank(n: number): string {
  return n.toLocaleString("en-US");
}

function ordinalSuffix(n: number): string {
  const mod10 = n % 10;
  const mod100 = n % 100;
  if (mod10 === 1 && mod100 !== 11) return "st";
  if (mod10 === 2 && mod100 !== 12) return "nd";
  if (mod10 === 3 && mod100 !== 13) return "rd";
  return "th";
}
